targets.root_selector:
([($a := data.viewer.accounts[0]; $s := $toMillis(($d := '${cf_period_start}'; $contains($d, /^[0-9]{4}-[0-9]{2}-[0-9]{2}/) ? $substring($d, 0, 10) : '1970-01-01') & 'T00:00:00Z'); $e := $toMillis(($d := '${cf_period_end}'; $contains($d, /^[0-9]{4}-[0-9]{2}-[0-9]{2}/) ? $substring($d, 0, 10) : '1970-01-01') & 'T00:00:00Z');
  $len := $e > $s ? $e - $s : 86400000; $f := $max([($toMillis($now()) - $s) / $len, 86400000 / $len]);
  $pace := function($used, $included) { $round(($used ? $used : 0) / $f / $included * 100, 1) };
  $d1 := $a.ds[0].dimensions.date; $kv := $a.ks[0].dimensions.date;
  $exists($a) and $s > 0 and $e > $s ? [{ 'product': 'Workers 請求', 'pct': $pace($sum($a.w.sum.requests), 10000000) },
   { 'product': 'D1 讀取列', 'pct': $pace($sum($a.d.sum.rowsRead), 25000000000) },
   { 'product': 'D1 寫入列', 'pct': $pace($sum($a.d.sum.rowsWritten), 50000000) },
   { 'product': 'D1 儲存', 'pct': $round(($b := $sum($a.ds[dimensions.date = $d1].max.databaseSizeBytes); $b ? $b : 0) / 5000000000 * 100, 1) },
   { 'product': 'KV 讀取', 'pct': $pace($sum($a.k[dimensions.actionType = 'read'].sum.requests), 10000000) },
   { 'product': 'KV 寫入', 'pct': $pace($sum($a.k[dimensions.actionType = 'write'].sum.requests), 1000000) },
   { 'product': 'KV 儲存', 'pct': $round(($b := $sum($a.ks[dimensions.date = $kv].max.byteCount); $b ? $b : 0) / 1000000000 * 100, 1) }]
  : [])])
